use anyhow::Result;
use sims_runtime::original_session::draw_parent::{State,WorldScene,WorldComposition,WorldClassification};
use sims_vm::scheduler::clock::profiler::Buffer;
type Saved=(State,WorldScene,WorldComposition,sims_sim::Simulation,Buffer,sims_vm::interface::state::State,WorldClassification);
fn diff(a:&serde_json::Value,b:&serde_json::Value,path:&str,out:&mut Vec<serde_json::Value>){if a==b||out.len()>=400{return;}match(a,b){(serde_json::Value::Object(a),serde_json::Value::Object(b))=>{for k in a.keys().chain(b.keys()).collect::<std::collections::BTreeSet<_>>(){diff(&a.get(k).cloned().unwrap_or_default(),&b.get(k).cloned().unwrap_or_default(),&format!("{path}/{k}"),out);}},(serde_json::Value::Array(a),serde_json::Value::Array(b))if a.len()==b.len()=>{for(i,(a,b))in a.iter().zip(b).enumerate(){diff(a,b,&format!("{path}/{i}"),out);}},_=>out.push(serde_json::json!({"path":path,"left":a,"right":b}))}}
fn main()->Result<()>{let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");let a:serde_json::Value=serde_json::from_slice(&std::fs::read(root.join("fixtures/private/goth-following-rows-20261101-first/resident-first.json"))?)?;let b:serde_json::Value=serde_json::from_slice(&std::fs::read(root.join("fixtures/private/goth-visible-sprite-20261101-first/no-raster.json"))?)?;let av:Saved=sims_fixtures::Store::open(root.join("fixtures/private/goth-following-rows-20261101-first/resident-first.store"))?.get_value(&serde_json::from_value(a["frontier"].clone())?)?;let bv:Saved=sims_fixtures::Store::open(root.join("fixtures/private/goth-visible-sprite-20261101-first/no-raster.store"))?.get_value(&serde_json::from_value(b["frontier"].clone())?)?;let mut out=vec![];diff(&serde_json::to_value(av)?,&serde_json::to_value(bv)?,"",&mut out);println!("{}",serde_json::to_string_pretty(&out)?);Ok(())}
